<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import EmptyState from '../components/EmptyState.vue'
import LoadingState from '../components/LoadingState.vue'
import { useProjectStore } from '../stores/projects'
import { useTaskStore } from '../stores/tasks'
import type { Project, Task } from '../types'
const router = useRouter(); const projects = ref<Project[]>([]); const tasks = ref<Task[]>([]); const loading = ref(true); const projectStore = useProjectStore(); const taskStore = useTaskStore()
onMounted(async () => { [projects.value, tasks.value] = await Promise.all([projectStore.getAll(), taskStore.getAll()]); loading.value = false })
const completed = computed(() => tasks.value.filter((task) => task.status === 'Done').length); const progress = computed(() => tasks.value.length ? Math.round(completed.value / tasks.value.length * 100) : 0)
</script>
<template><div><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-medium text-primary">Workspace overview</p><h1 class="mt-1 text-3xl font-bold tracking-tight">Keep work moving forward.</h1><p class="mt-2 text-sm text-secondary">Here’s a clear view of what your team is building.</p></div><div class="flex gap-3"><button @click="router.push('/tasks/new')" class="rounded-lg border border-border bg-surface px-4 py-2.5 text-sm font-semibold hover:bg-surface-muted">Add task</button><button @click="router.push('/projects/new')" class="rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary-hover">+ New project</button></div></div><LoadingState v-if="loading" class="mt-8" label="Loading workspace overview" :rows="4" /><template v-else><EmptyState v-if="!projects.length && !tasks.length" class="mt-8" title="Your workspace is ready" description="Create a project or task to begin tracking your team's work." action-label="Create a project" @action="router.push('/projects/new')" /><template v-else><section class="mt-8 grid gap-5 sm:grid-cols-2 xl:grid-cols-4"><article v-for="metric in [{ label: 'Active projects', value: projects.filter(p => p.status === 'Active').length, detail: '+2 this month' }, { label: 'Total tasks', value: tasks.length, detail: 'Across all projects' }, { label: 'Completed', value: completed, detail: `${progress}% completion rate` }, { label: 'Team members', value: 4, detail: '2 active today' }]" :key="metric.label" class="rounded-panel border border-border bg-surface p-5"><p class="text-sm font-medium text-secondary">{{ metric.label }}</p><p class="mt-3 text-3xl font-bold">{{ metric.value }}</p><p class="mt-2 text-xs text-success">{{ metric.detail }}</p></article></section><section class="mt-8 grid gap-6 xl:grid-cols-5"><article class="rounded-panel border border-border bg-surface p-6 xl:col-span-3"><div class="flex items-center justify-between"><div><h2 class="font-bold">Project progress</h2><p class="mt-1 text-sm text-secondary">Your current project health.</p></div><button @click="router.push('/projects')" class="text-sm font-semibold text-primary">View all</button></div><div class="mt-6 space-y-5"><button v-for="project in projects.slice(0, 3)" :key="project.id" @click="router.push(`/projects/${project.id}`)" class="w-full text-left"><div class="flex justify-between text-sm"><span class="font-semibold">{{ project.title }}</span><span class="text-secondary">{{ project.progress }}%</span></div><div class="mt-2 h-2 overflow-hidden rounded-full bg-surface-muted"><div class="h-full rounded-full bg-primary" :style="{ width: `${project.progress}%` }" /></div></button></div></article><article class="rounded-panel border border-border bg-surface p-6 xl:col-span-2"><h2 class="font-bold">Recent activity</h2><div class="mt-5 space-y-5"><div v-for="activity in ['Maya completed final landing copy', 'Jordan moved Android beta build forward', 'Sam joined Mobile App Launch']" :key="activity" class="flex gap-3"><span class="mt-1 h-2 w-2 rounded-full bg-primary" /><p class="text-sm text-secondary">{{ activity }}<span class="block pt-1 text-xs text-muted">Today</span></p></div></div></article></section></template></template></div></template>
